import ast

def truthy(v):
    if v is True:
        return True
    if isinstance(v, str) and v.strip().lower() == 'true':
        return True
    return False

def qualifies(attrs):
    if not attrs:
        return False, False, False
    bike = truthy(attrs.get('BikeParking'))
    bp_raw = attrs.get('BusinessParking')
    bp_any = False
    if bp_raw is not None:
        bp_parsed = bp_raw
        if isinstance(bp_raw, str):
            try:
                bp_parsed = ast.literal_eval(bp_raw)
            except Exception:
                bp_parsed = None
                # fallback substring
                if 'True' in bp_raw:
                    bp_any = True
        if isinstance(bp_parsed, dict):
            bp_any = any(truthy(v) for v in bp_parsed.values())
    return (bike or bp_any), bike, bp_any

